with valid_departments as (select * from departments where dept_name = 'Sales'), budget_bucket_summary as (select case when budget >= 3419000 then 'high' when budget >= 1261000 then 'mid' else 'low' end as budget_bucket, count(budget) as budget_count from valid_departments group by case when budget >= 3419000 then 'high' when budget >= 1261000 then 'mid' else 'low' end) select * from budget_bucket_summary order by budget_bucket
